const panelDesign = {"html":"<main><header><div><span class=\"eyebrow\">GitHub · review companion</span><h1 id=\"title\">PR review navigator</h1><p id=\"branch\" class=\"muted\"></p></div><span class=\"pill\">Local checklist</span></header>\n<div class=\"stats\"><div><strong id=\"loaded\">0</strong><small>FILES LOADED</small></div><div><strong id=\"checked\">0</strong><small>CHECKED HERE</small></div><div><strong id=\"tests\">0</strong><small>TEST FILES</small></div></div>\n<div class=\"toolbar\"><input id=\"search\" type=\"search\" placeholder=\"Find a file or folder…\" aria-label=\"Find a file or folder\"><div class=\"row\" style=\"margin-top:9px\"><select id=\"filter\" aria-label=\"Filter files\" class=\"grow\"><option value=\"all\">All files</option><option value=\"todo\">Not checked here</option><option value=\"test\">Tests and specs</option></select><button id=\"refresh\">Refresh</button><a id=\"files-link\" class=\"muted\">Files changed ↗</a></div></div>\n<p id=\"notice\" class=\"muted\"></p><div id=\"files\" class=\"list\"></div><p id=\"error\" class=\"error\" role=\"alert\"></p>\n<details class=\"card\"><summary>PR description</summary><p id=\"description\" style=\"white-space:pre-wrap;font-size:12px\"></p></details><details class=\"card\"><summary id=\"threads-title\">Loaded review threads</summary><div id=\"threads\" class=\"list\" style=\"margin-top:12px\"></div></details>\n<p class=\"muted\">Checked marks are your local session checklist—not GitHub’s Viewed state or a submitted review. Refresh after opening Files changed or loading more content.</p></main>\n","css":"*{box-sizing:border-box}body{margin:0}main{padding:16px;max-width:900px;margin:auto}header{display:flex;align-items:start;justify-content:space-between;gap:10px;margin-bottom:16px}h1{font-size:20px;line-height:1.25;letter-spacing:-.4px;margin:4px 0 8px}h2{font-size:14px;margin:0 0 10px}p{margin:6px 0;line-height:1.6}.eyebrow{font-size:10px;letter-spacing:1.6px;text-transform:uppercase;opacity:.6}.muted,small{opacity:.65;font-size:12px;line-height:1.5}.card{padding:14px;border-radius:14px;background:color-mix(in srgb,CanvasText 5%,Canvas);margin:12px 0}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.row>*{min-width:0}.grow{flex:1}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(145px,100%),1fr));gap:10px}button,input,select{font:inherit}button{border:0;border-radius:9px;padding:8px 11px;background:color-mix(in srgb,CanvasText 8%,Canvas);color:inherit;cursor:pointer}button:hover{background:color-mix(in srgb,CanvasText 13%,Canvas)}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--kudium-primary);outline-offset:3px}.primary{background:var(--kudium-primary);color:var(--kudium-primary-contrast);font-weight:650}button:disabled{opacity:.4;cursor:default}input,select{min-width:0;width:100%;padding:9px 10px;border:0;border-radius:9px;background:color-mix(in srgb,CanvasText 7%,Canvas);color:inherit}label{display:block;font-size:12px}label input,label select{margin-top:6px}a{color:inherit;text-decoration:none;overflow-wrap:anywhere}a:hover{text-decoration:underline}.list{display:grid;gap:6px}.item{width:100%;padding:11px;text-align:left;background:color-mix(in srgb,CanvasText 4%,Canvas);border-radius:10px}.item strong,.item small{display:block;overflow-wrap:anywhere}.item strong{font-size:12px;font-weight:550}.pill{font-size:10px;padding:5px 8px;background:color-mix(in srgb,var(--kudium-primary) 15%,Canvas);border-radius:99px;white-space:nowrap}.error{color:light-dark(#ad2828,#ff9b9b)}[hidden]{display:none!important}details summary{cursor:pointer;font-size:13px}.stats{display:flex;gap:16px;flex-wrap:wrap;margin:12px 0}.stats strong{display:block;font-size:22px}.stats small{font-size:10px}.empty{padding:18px;text-align:center;opacity:.6;font-size:13px}#error:empty{display:none}.toolbar{position:sticky;top:0;background:Canvas;padding:10px 0;z-index:1}code{font-family:ui-monospace,monospace;font-size:11px;overflow-wrap:anywhere}@media(max-width:340px){main{padding:12px}h1{font-size:18px}.card{padding:11px}}\n\nheader>button,header>.pill{flex-shrink:0}header>div{min-width:0}.row>button,header>button{white-space:nowrap}.item{white-space:normal}\n.item .grow{white-space:normal;overflow-wrap:anywhere}\n\n.primary:hover{background:var(--kudium-primary);filter:brightness(1.08)}\n","script":"let prData;\nconst el=id=>document.getElementById(id);\nasync function action(id,payload){el('error').textContent='';try{await kudiumHookPanel.invoke(id,payload);}catch(error){el('error').textContent=error.message;}}\nfunction renderFiles(){if(!prData)return;const query=el('search').value.toLowerCase(),filter=el('filter').value;\n  const list=prData.files.filter(file=>file.path.toLowerCase().includes(query)&&(filter!=='todo'||!file.reviewed)&&(filter!=='test'||file.test));\n  el('files').replaceChildren(...list.map(file=>{\n    const row=document.createElement('div');row.className='item row';\n    const jump=document.createElement('button');jump.className='grow';jump.style.cssText='background:none;padding:0;text-align:left';\n    const name=document.createElement('strong');name.textContent=file.path;const detail=document.createElement('small');detail.textContent=file.folder+(file.test?' · test':'')+(file.additions||file.deletions?' · +'+file.additions+' −'+file.deletions:'');jump.append(name,detail);jump.onclick=()=>action('pr-jump',{index:file.index});\n    const check=document.createElement('button');check.textContent=file.reviewed?'✓':'○';check.setAttribute('aria-label',(file.reviewed?'Uncheck ':'Mark checked ')+file.path);check.setAttribute('aria-pressed',String(file.reviewed));check.onclick=()=>action('pr-check',{index:file.index});row.append(jump,check);return row;\n  }));if(!list.length){const empty=document.createElement('p');empty.className='empty';empty.textContent=prData.files.length?'No files match this filter.':'Open Files changed, then Refresh to build your review map.';el('files').append(empty);}\n}\nel('search').oninput=renderFiles;el('filter').onchange=renderFiles;el('refresh').onclick=()=>action('pr-refresh');\nkudiumHookPanel.onUpdate(output=>{prData=output.content.data;el('title').textContent=prData.title;el('branch').textContent=prData.branch?'Branch · '+prData.branch:'';el('loaded').textContent=prData.files.length;el('checked').textContent=prData.files.filter(file=>file.reviewed).length;el('tests').textContent=prData.files.filter(file=>file.test).length;el('files-link').href=prData.url+'/files';el('notice').textContent='Showing '+prData.files.length+' loaded files'+(prData.total>prData.files.length?' of '+prData.total+' reported by GitHub':'')+'.';el('description').textContent=prData.description||'Open the conversation tab, then refresh to read the description.';el('threads-title').textContent=prData.comments.length+' loaded review threads';el('threads').replaceChildren(...prData.comments.map(text=>{const p=document.createElement('p');p.className='item';p.textContent=text;return p;}));renderFiles();});\n"};
if (!/^\/[^/]+\/[^/]+\/pull\/\d+(?:\/|$)/.test(location.pathname)) return;
let prNodes = [], prReviewed = new Set(), prIdentity = location.pathname.match(/^\/[^/]+\/[^/]+\/pull\/\d+/)[0];
const storageKey = 'kudium-pr-notes:' + prIdentity;
try { prReviewed = new Set(JSON.parse(sessionStorage.getItem(storageKey)||'[]').filter(path => typeof path === 'string')); } catch {}
const scanPR = () => {
  const roots = [...document.querySelectorAll('.file[data-path], [data-file-path]')];
  const deduped = new Map();
  for (const root of roots) {
    const path = root.getAttribute('data-path') || root.getAttribute('data-file-path');
    if (!path || deduped.has(path)) continue;
    deduped.set(path,{node:root,path});
  }
  prNodes = [...deduped.values()].slice(0,150);
  const files = prNodes.map(({node,path},index) => ({ index,path:path.slice(0,500),folder:path.includes('/')?path.slice(0,path.lastIndexOf('/')).slice(0,180):'Root',
    additions:Number(node.querySelector('.diffstat .color-fg-success')?.textContent?.replace(/\D/g,'')) || 0,
    deletions:Number(node.querySelector('.diffstat .color-fg-danger')?.textContent?.replace(/\D/g,'')) || 0,
    reviewed:prReviewed.has(path), test:/test|spec|__tests__/i.test(path) }));
  while (JSON.stringify(files).length > 40000) { files.pop(); prNodes.pop(); }
  const comments = [...document.querySelectorAll('.review-thread, .js-resolvable-timeline-thread-container')].slice(0,40).map(node => node.innerText.trim().slice(0,420)).filter(Boolean);
  const description = document.querySelector('.js-comment-body, [data-testid="issue-body"]')?.innerText?.trim().slice(0,1800) || '';
  const filesTab = document.querySelector('#files_tab_counter, [data-content="Files changed"] .Counter');
  return { title:document.querySelector('.js-issue-title, [data-testid="issue-title"]')?.textContent?.trim().slice(0,180) || document.title.split('·')[0].trim().slice(0,180),
    url:location.origin+prIdentity, branch:document.querySelector('.head-ref')?.textContent?.trim().slice(0,160) || '', files, comments, description,
    total:Number(filesTab?.textContent?.replace(/\D/g,'')) || files.length };
};
const publishPR = async () => context.panel.update({id:'pr',title:'PR review navigator',content:{type:'html',...panelDesign,data:scanPR()},actions:prActions});
const prActions = [{id:'pr-refresh',label:'Refresh'},{id:'pr-jump',label:'Jump to file'},{id:'pr-check',label:'Mark checked'}];
context.panel.onAction('pr-refresh',async()=>{await publishPR();return {refreshed:true};});
context.panel.onAction('pr-jump',async payload=>{
  const entry=prNodes[Number(payload?.index)]; if (!entry || !Number.isInteger(payload?.index)) throw new Error('Refresh the file list first.');
  entry.node.scrollIntoView({behavior:'auto',block:'start'}); return {path:entry.path};
});
context.panel.onAction('pr-check',async payload=>{
  const entry=prNodes[Number(payload?.index)]; if (!entry || !Number.isInteger(payload?.index)) throw new Error('Refresh the file list first.');
  prReviewed.has(entry.path)?prReviewed.delete(entry.path):prReviewed.add(entry.path);
  try { sessionStorage.setItem(storageKey,JSON.stringify([...prReviewed].slice(0,1000))); } catch {}
  await publishPR(); return {checked:prReviewed.has(entry.path)};
});
await context.panel.show({id:'pr',title:'PR review navigator',reveal:false,content:{type:'html',...panelDesign,data:scanPR()},actions:prActions});
